sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var response = JSON.parse(inputs.response_body);
        outputs.translated_text = response.translatedTexts[0];
    } catch (e) {
        gs.error("Error when processing JSON: " + e.message);
        outputs.translated_text = "";
    }
})(inputs, outputs);

